/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(formDataSourceStr(AVAEDIAddress,AVAEDIAddress))]
internal final class AVAEDIAddressFrm_AVAEDIAddressDS_Extension
{
}

Method.Source:
/// <summary>
/// desigend from AVA
/// </summary>
public void init()
{
    next init();
    Args            args;
    FormRun         formRun = this.formRun();

    args  = formRun.args();

    if (args)
    {
        switch (args.dataset())
        {
            case tableNum(CustInvoiceJour) :
                this.allowCreate(true);
                this.allowDelete(true);
                this.allowEdit(true);
                break;
            default:
        }
    }

}

/// <summary>
/// designed from AVA
/// </summary>
public void initValue()
{
    next initValue();

    FormDataSource              ediAddress_ds = this;
    AVAEDIAddress               EDiAddress;
    SalesTable                  parentSalesTable;
    AVAEDIAddress               addressRef;
    AVAEDISalesTableOrig        salesTableOrig;
    FormRun                     formRun = this.formRun();

    EDiAddress = ediAddress_ds.cursor();
    parentSalesTable  = EDiAddress.joinParent();
    EDiAddress.Num         = SalesTable::findRecId(EDiAddress.RefRecId).SalesId;
    if (EDiAddress.EDIGUID == emptyGuid())
    {
        select firstonly EDIGUID from addressRef
            join salesTableOrig
            where salesTableOrig.EDIGUID == addressRef.EDIGUID
                && salesTableOrig.SalesId == EDiAddress.Num;

        if (addressRef.RecId != 0)
        {
            EDiAddress.EDIGUID = addressRef.EDIGUID;
        }
        else
        {
            salesTableOrig = AVAEDISalesTableOrig::findRefRecId(EDiAddress.RefRecId);

            if (salesTableOrig.EDIGUID != emptyGuid())
            {
                EDiAddress.EDIGUID = salesTableOrig.EDIGUID;
            }
            else
            {
                EDiAddress.EDIGUID = newGuid();
            }
        }
    }

    if (formRun && formRun.args() && formRun.args().dataset() == tableNum(CustInvoiceJour))
    {
        CustInvoiceJour   callerCustInvoiceJour = formRun.args().record();
        EDiAddress.AccountNum = callerCustInvoiceJour.InvoiceAccount;
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean validateWrite()
{
    boolean ret;

    FormDataSource              ediAddress_ds = this;
    AVAEDIAddress               EDiAddress;
    SalesTable                  parentSalesTable;
    AVAEDIAddress               addressRef;
    AVAEDISalesTableOrig        salesTableOrig;

    EDiAddress = ediAddress_ds.cursor();
    parentSalesTable  = EDiAddress.joinParent();
    EDiAddress.Num         = SalesTable::findRecId(EDiAddress.RefRecId).SalesId;
    if (EDiAddress.EDIGUID == emptyGuid())
    {
        select firstonly EDIGUID from addressRef
            join salesTableOrig
            where salesTableOrig.EDIGUID == addressRef.EDIGUID
                && salesTableOrig.SalesId == EDiAddress.Num;

        if (addressRef.RecId != 0)
        {
            EDiAddress.EDIGUID = addressRef.EDIGUID;
        }
        else
        {
            salesTableOrig = AVAEDISalesTableOrig::findRefRecId(EDiAddress.RefRecId);

            if (salesTableOrig.EDIGUID != emptyGuid())
            {
                EDiAddress.EDIGUID = salesTableOrig.EDIGUID;
            }
            else
            {
                EDiAddress.EDIGUID = newGuid();
            }
        }
    }

    ret = next validateWrite();

    return ret;
}
